# Extend every image edge by the same fraction of the longer image side, in pixels.
def catalog_window_bounds(shape: tuple[int, int]) -> tuple[float, float, float, float]:
    margin = max(shape)*CATALOG_WINDOW_MARGIN
    return -margin, shape[1]+margin, -margin, shape[0]+margin


# Retain finite projected references inside the shared window and rank them by catalogue magnitude.
def catalog_pixels(catalog: ReferenceCatalog, wcs: WCS, shape: tuple[int,int], *,
                   clip: bool = True) -> tuple[np.ndarray, SkyCoord]:
    x, y = wcs.world_to_pixel(catalog.sky)
    xy = np.column_stack((x, y))
    good = np.isfinite(xy).all(axis=1)
    if clip:
        left, right, bottom, top = catalog_window_bounds(shape)
        good &= (x > left) & (x < right) & (y > bottom) & (y < top)
    xy, sky, mag = xy[good], catalog.sky[good], catalog.mag[good]
    order = np.argsort(np.where(np.isfinite(mag), mag, np.inf))
    return xy[order], sky[order]


# Apply the selected virtual image-axis reflection without modifying input positions.
def flip_points(xy: np.ndarray, shape: tuple[int,int], mode: str) -> np.ndarray:
    transformed = xy.copy()
    if 'x' in mode:
        transformed[:,0] = shape[1] - 1 - transformed[:,0]
    if 'y' in mode:
        transformed[:,1] = shape[0] - 1 - transformed[:,1]
    return transformed


# Express a virtually reflected solution in the original image coordinate system.
def unflip_wcs(fitted: WCS, shape: tuple[int,int], mode: str) -> WCS:
    """Express a WCS fitted to virtual flipped pixels in original FITS pixels."""
    if not mode:
        return fitted
    result = fitted.deepcopy()
    signs = np.array([-1 if 'x' in mode else 1, -1 if 'y' in mode else 1])
    crpix = result.wcs.crpix.copy()
    if 'x' in mode:
        crpix[0] = shape[1] + 1 - crpix[0]
    if 'y' in mode:
        crpix[1] = shape[0] + 1 - crpix[1]
    result.wcs.crpix = crpix
    result.wcs.cd = fitted.pixel_scale_matrix @ np.diag(signs)
    return result


_WCS_KEYS = re.compile(
    r'^(?:WCSAXES[A-Z]?|WCSNAME[A-Z]?|'
    r'WCSDIM|WAT\d+_\d+|'
    r'(?:CTYPE|CRVAL|CRPIX|CUNIT|CDELT|CROTA|CNAME|CRDER|CSYER)\d+[A-Z]?|'
    r'(?:CD|PC|PV|PS)\d+_\d+[A-Z]?|'
    r'(?:LONPOLE|LATPOLE|RADESYS|RADECSYS|EQUINOX)[A-Z]?|'
    r'(?:[AB]P?_(?:ORDER|DMAX|\d+_\d+))|'
    r'(?:CPERR|CQERR|DPERR|DQERR|D2IMERR)\d+|'
    r'(?:AXISCORR|D2IMFILE|D2IMEXT|D2IMERR|NPOLFILE|SIPNAME)|'
    r'(?:CPDIS|CQDIS|D2IMDIS|D2IM|DET2IM|DP|DQ)\d+'
    r'(?:\.[A-Z0-9_.]+)?)$')


# Measure the centre and width/height as great-circle separations between opposite edge midpoints.
def field_extents(wcs: WCS, shape: tuple[int, int]) -> tuple[SkyCoord, u.Quantity]:
    height, width = shape
    x, y = (width-1)/2, (height-1)/2
    center = wcs.pixel_to_world(x, y)
    horizontal = wcs.pixel_to_world([-.5, width-.5], [y, y])
    vertical = wcs.pixel_to_world([x, x], [-.5, height-.5])
    spans = u.Quantity([horizontal[0].separation(horizontal[1]),
                        vertical[0].separation(vertical[1])]).to(u.arcsec)
    return center, spans


# Preserve the established shorter-side definition for pointing statistics and search windows.
def field_geometry(wcs: WCS, shape: tuple[int, int]) -> tuple[SkyCoord, u.Quantity]:
    center, spans = field_extents(wcs, shape)
    return center, min(spans)


# Share sexagesimal centre and adaptive angular-size formatting between terminal and every plot layout.
def image_geometry_label(wcs: WCS, shape: tuple[int, int]) -> str:
    center, spans = field_extents(wcs, shape)
    ra = center.ra.to_string(unit=u.hourangle, sep=('h', 'm', 's'), precision=2, pad=True)
    dec = center.dec.to_string(unit=u.deg, sep=('d', 'm', 's'), precision=1, pad=True, alwayssign=True)
    # Choose units using unrounded sizes; mixed-size rectangles retain arcminutes.
    arcmin = spans.to_value(u.arcmin)
    unit = u.arcsec if max(arcmin) < 1 else (u.deg if min(arcmin) > 50 else u.arcmin)
    width, height = spans.to_value(unit)
    label = 'deg' if unit == u.deg else unit.to_string()
    return f'Image Center: {ra}, {dec} | FOV: {width:.1f} x {height:.1f} {label}'


# Reuse the same angular field definition for annotations and pointing-recovery displacements.
def pointing_offset(wcs: WCS, shape: tuple[int, int], requested: SkyCoord
                    ) -> tuple[SkyCoord, float, float]:
    center, shorter_span = field_geometry(wcs, shape)
    separation = float(requested.separation(center).arcsec)
    return center, separation, separation/shorter_span.to_value(u.arcsec)


